#include <stdint.h>
#include "main.h"
#if !defined(__SOFT_FP__) && defined(__ARM_FP)
  #warning "FPU is not initialized, but the project is compiling for an FPU. Please initialize the FPU before use."
#endif


int main(void)
{
	RCC_AHB1ENR_t volatile *const ptrClkCntrlReg = (RCC_AHB1ENR_t*)0x40023830;
	GPIOx_MODER_t volatile *const ptrPortDModeReg= (GPIOx_MODER_t*)0x40020C00;
	GPIOx_ODR_t volatile *const ptrPortDOutReg= (GPIOx_ODR_t*)0x40020C14;


	// Enable clock for GPIOD pheripheral
	ptrClkCntrlReg->gpiod_en = 1;

	//Configure the mode of IO pin as output
	ptrPortDModeReg->moder_12 = 1; //Clear 24th and 25th bit

	while(1){
		//Set 12th bit to high
		ptrPortDOutReg->moder_12 = 1;
		/* Loop for some delay */
		for(int i=0;i<100000;i++);

		//Set 12th bit to high
		ptrPortDOutReg->moder_12 = 0;
		/* Loop for some delay */
		for(int i=0;i<100000;i++);
	}
}

